layers.vertex:
attribute vec3 aO; attribute float aT, aK; attribute vec4 aD; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > 1.00){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vP = position.xy;
      if (aK > 2.5){                                          // Weave: a resource mote flies back to the caster on a curved path
        float k = clamp((u - aD.w)/.45, 0., 1.); if (u < aD.w || k >= 1.){ gl_Position = vec4(2.,2.,2.,1.); return; }
        float e = k*k*(3. - 2.*k); vec3 A = aO + vec3(0., 1.2, 0.), B = aD.xyz;
        vec3 side = normalize(cross(B - A, vec3(0., 1., 0.)))*sin(aD.w*37.)*.8;
        vec3 P = mix(A, B, e) + (side + vec3(0., .9, 0.))*sin(3.14159*e);
        vec4 mv = viewMatrix*vec4(P, 1.); float S = .09; mv.xy += position.xy*S; vU = k; gl_Position = projectionMatrix*mv; return; }
      if (aK < .5){ float S = .95; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else if (aK < 1.5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.2, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.34; float S = .5; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv; }   /* II snap on the chest */
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.2, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.3; float S = .75; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv; }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      float lum = 0., hot = 0., t = vU/1.00;
      if (vK < .5){
        float r = length(vP), e = pow(clamp(vU/.25, 0., 1.), 3.), R = .8 - .65*e, f = (vU < .033 ? 1.5 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += exp(-pow(abs(r - R)/.016, 2.4))*f; hot += lcore(r - R, .005)*f*.6;
        lum *= smoothstep(.95, .85, r); hot *= smoothstep(.95, .85, r);
      } else if (vK < 1.5){
        // II · control snap (only if the target was already Slowed): three thin angular ice shards slam inward (reverse ease-in)
        // and lock into a rigid star on the chest, 2-frame peak, hold, then crack and go — short, not a Stun
        float k = clamp(vU/.09, 0., 1.), e = k*k*k, lock = vU >= .09 && vU < .123 ? 1.8 : 1.;
        float f = step(0., vU)*(1. - smoothstep(.22, .35, vU));
        for (int i = 0; i < 3; i++){ float fi = float(i), an = fi*2.0944 + .52;
          vec2 dir = vec2(cos(an), sin(an)), nr = vec2(-dir.y, dir.x);
          vec2 c = dir*mix(.42, 0., e);                                   // each shard travels in from outside to the centre
          vec2 q = vP - c; float al = dot(q, dir), ac = dot(q, nr);
          float L = .2, w = .026*max(1. - abs(al)/L, 0.);                        // long, thin, pointed at both ends
          float sh = exp(-pow(ac/max(w, .002), 2.))*step(abs(al), L)*pow(max(1. - abs(al)/L, 0.), .4);
          lum += sh*1.1; hot += sh*exp(-pow(ac/max(w*.3, .001), 2.))*.6; }
        float r = length(vP), crk = vU > .2 ? exp(-pow((abs(sin(atan(vP.y, vP.x)*3.)) - .05)/.05, 2.))*smoothstep(.3, .05, r)*(1. - smoothstep(.2, .35, vU))*.5 : 0.;
        lum = (lum + crk)*f*lock; hot *= f*lock;
        lum *= smoothstep(.5, .4, r); hot *= smoothstep(.5, .4, r);
      } else {
        if (vK > 2.5){ float r = length(vP); float m = exp(-r*r*8.)*(1. - vU)*1.6;       // Weave mote
          vec3 o = uGold*m + vec3(1., .95, .8)*exp(-r*r*40.)*(1. - vU);
          if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); return; }
        // compact fire burst on the target: bright sphere pops, flame tongues flare out short and die fast
        float r = length(vP), a = atan(vP.y, vP.x), t2 = clamp(vU/.35, 0., 1.);
        float R = .12 + .25*(1. - pow(1. - t2, 3.)), fl = .5 + .5*sin(a*9. + 2.)*sin(a*4. - 1.);
        float body = exp(-r*r*(30. + 50.*t2))*(vU < .033 ? 2. : 1.4*(1. - t2));
        float tongues = pow(max(0., cos(a*6.))*fl, 2.)*smoothstep(R + .18*fl, R, r)*smoothstep(.05, .15, r)*(1. - t2);
        float rim = exp(-pow((r - R)/.03, 2.))*(1. - t2)*.8;
        lum += body*.6; hot = body*.3;                                     /* short cold flash */
        for (int i = 0; i < 7; i++){ float fi = float(i), hh = fract(sin(fi*37.7)*4375.5);
          float an = 3.14159 + (fi/6. - .5)*2.6 + (hh - .5)*.3;                 /* shards fly back and to the sides */
          vec2 dir = vec2(cos(an), sin(an) + .25), nr = vec2(-dir.y, dir.x);
          vec2 c = dir*(.06 + .45*(1. - pow(1. - t2, 2.)))*(.7 + .5*hh) + vec2(0., -.25*t2*t2);
          vec2 q = vP - c; float al = dot(q, normalize(dir)), ac = dot(q, normalize(nr));
          float sz = .035 + .025*hh; float sh = exp(-(abs(al)/(sz*1.8) + abs(ac)/(sz*.6))*2.5);
          lum += sh*(1. - t2)*1.2; hot += sh*(1. - t2)*.5; }
        lum *= smoothstep(.75, .62, r); hot *= smoothstep(.75, .62, r);
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
